import"./chunk-2NFLSA4Y.js";var i={lorentzForce:{theory:{concept:"[[The Lorentz force is the force that a magnetic field exerts on a moving charged particle: F = q\xB7v \xD7 B.]] It is perpendicular both to the velocity and to the field, so it changes the direction of motion but not the speed, and it does no work. A charge at rest, or one moving along the field, feels no magnetic force. (The full Lorentz force also includes the electric force q\xB7E; this experiment shows only its magnetic part.)"},param:{speed:"Initial speed",field:"Magnetic field",charge:"Charge",mass:"Mass",angle:"Angle between v and B",timeStep:"Time step"},hint:{speed:"At zero speed there is no magnetic force.",field:"Positive: B points up (along +z). Negative: B points down. Zero turns the field off.",charge:"Reverse the sign to reverse the bend. A neutral particle does not feel this force.",mass:"A larger mass makes the charge harder to turn. 1 mg = 0.000001 kg.",angle:"90\xB0: the charge starts across the field and moves on a circle. Smaller angles add motion along the field: the path becomes a helix. 0\xB0: along the field, no force at all."},preset:{rest:"At rest",slow:"3 m/s",fast:"6 m/s",in:"Down (\u22121 T)",out:"Up (+1 T)",off:"No field",negative:"Negative",positive:"Positive",neutral:"Neutral",light:"1 mg",heavy:"2 mg",across:"90\xB0 (circle)",helix:"60\xB0 (helix)",along:"0\xB0 (along B)"},measure:{force:"Magnetic force",radius:"Orbit radius (0: no orbit)",period:"Period (0: no orbit)",fx:"Force component along x",fy:"Force component along y",angularSpeed:"Angular speed",pitch:"Pitch of the helix (0: no turning)",vParallel:"Speed along the field",vPerp:"Speed across the field"},graph:{force:"Force components over time",energy:"Kinetic energy stays constant"},view:{field:"Field arrows",radius:"Orbit radius",up:"B = {value}, up (along +z)",down:"B = {value}, down (along \u2212z)",zero:"B = 0: no magnetic field",positive:"+",negative:"\u2212",neutral:"0",straight:"Straight path: F = 0",alongField:"Moving along the field: F = 0",stationary:"At rest: F = 0",circle:"Circle: r = {r}, one turn in T = {period}",helix:"Helix: r = {r}, T = {period}, pitch {pitch}",legend:"v: velocity \xB7 F: force, perpendicular to both v and B \xB7 thin arrows: the field B \xB7 the circle is always drawn the same size; the view follows the charge along B"},section:{direction:{title:"Which way does the force point?",text:"For a positive charge use the right-hand rule for v \xD7 B: fingers along v, bend them towards B, the thumb shows F. For a negative charge reverse the result. With v along +x and B up, a positive charge is first pushed along \u2212y. Turn the picture: v, B and F are perpendicular to one another."},radius:{title:"A tighter or wider circle",text:"[[A stronger field or larger charge magnitude makes a tighter circle.]] Greater speed or mass makes a wider circle. Changing the charge or field sign reverses the direction, but keeps the radius unchanged."},helix:{title:"Circles that drift: the helix",text:"Split the velocity into a part across the field, v\u22A5 = v\xB7sin \u03B1, and a part along it, v\u2225 = v\xB7cos \u03B1. Only v\u22A5 feels the force, so the charge circles around B with r = m\xB7v\u22A5/|qB|, while v\u2225 carries it along the field unchanged. Together they make a helix; each turn moves it the pitch p = v\u2225\xB7T further. Charged particles from the Sun spiral like this along the Earth's field lines towards the poles, where they make the northern lights."},try:{title:"Compare the paths",text:"Start the animation. Double B while keeping speed fixed, then compare the radius. Turn B off to see a straight path. At higher levels reverse the charge, compare the force components on the graph, and change the angle to turn the circle into a helix."}},formula:{force:"Magnetic force for perpendicular motion; B is the field magnitude",radius:"Circle radius for motion across the field (\u03B1 = 90\xB0); use SI units",general:"Full Lorentz force; the electric field is zero in this experiment",energy:"The magnetic force does no work",helix:"Helix: the part across the field turns, the part along it moves on; p is the distance per turn",period:"Orbit period for a moving charged particle in a nonzero field"},assumption:{field:"The external magnetic field is uniform and constant. The electric field is zero.",helix:"The velocity may have a part along the field; that part stays unchanged, so the path is a circle (\u03B1 = 90\xB0), a helix, or a straight line along the field (\u03B1 = 0\xB0).",ideal:"This is an ideal point test charge at nonrelativistic speed. Gravity, drag, radiation and the charge's own fields are omitted.",scale:"The particle and vector arrows are schematic and not to scale. A circular path is always drawn with the same size, and the view follows the charge along the field; the real radius and pitch are in the readings.",zero:"Zero radius or period means no circular orbit, rather than a circle of zero size. If q = 0 or B = 0, the moving particle follows a straight path; if v = 0, it stays at rest."},challenge:{straight:{title:"Travel straight",description:"Make a particle moving at least 1 m/s experience zero magnetic force.",hint:"Turn the magnetic field off."},radius:{title:"A circle of radius 1.5 m",description:"Find a setup with orbit radius 1.5 m.",hint:"Use speed 3 m/s and field 2 T with the default charge and mass."},force:{title:"Reach 6 \xB5N",description:"Make the magnetic force equal 6 \xB5N.",hint:"Use speed 6 m/s and field 1 T with charge 1 \xB5C."},up:{title:"Push along +y",description:"Create an initial force along +y (the y axis in the picture) larger than 1 \xB5N.",hint:"Keep B positive and use a negative charge."},energy:{title:"Turn without losing energy",description:"Run for at least 3 seconds with a nonzero magnetic force and preserve the initial kinetic energy.",hint:"Choose a moving charge and a nonzero field. Watch energy while the force turns."},parallel:{title:"Along the field lines",description:"With a field and a charge switched on, make a particle moving at least 1 m/s feel no force.",hint:"The force depends only on the part of v across B. Change the angle."},helix:{title:"A helix with a 10 m pitch",description:"Make the charge move on a helix that advances 10 m (\xB1 0.2 m) per turn.",hint:"p = v\xB7cos \u03B1 \xB7 T. With the default charge, mass and field, T \u2248 6.28 s; with 3 m/s try an angle near 58\xB0."},period:{title:"A period of 4\u03C0 seconds",description:"Make one orbit take about 12.57 seconds.",hint:"Use mass 2 mg, charge 1 \xB5C and field 1 T, with nonzero speed."}}}},a={sim:i};export{a as default,i as sim};
